      }
      return { content: [{ type: 'text', text: `opened client ${client_id}` }] };
    }
    case 'client_put': {
      const { client_id, key, value } = args;
      assertNonEmptyString(client_id, 'client_id');
      assertNonEmptyString(key, 'key');
      assertNonEmptyString(value, 'value');
      const store = clients.get(client_id);
      if (!store) {
        throw new RpcError(-32602, `unknown client: ${client_id}`);
      }
      store.set(key, value);
      return { content: [{ type: 'text', text: `stored ${key} for client ${client_id}` }] };
    }
    case 'client_get': {
      const { client_id, key } = args;
      assertNonEmptyString(client_id, 'client_id');
      assertNonEmptyString(key, 'key');
      const store = clients.get(client_id);
      if (!store) {
        throw new RpcError(-32602, `unknown client: ${client_id}`);
      }
      if (!store.has(key)) {
        throw new RpcError(-32602, `unknown key: ${key}`);
      }
      return { content: [{ type: 'text', text: store.get(key) }] };
    }
    default:
      throw new RpcError(-32601, `unknown tool: ${name}`);
  }
}
