import { listTools, callTool } from './server.mjs';

// Verify schemas have additionalProperties:false
const tools = await listTools();
for (const t of tools) {
  console.log(t.name, 'additionalProperties:', t.inputSchema.additionalProperties, 'required:', t.inputSchema.required);
}

// Reject unknown tool
try { await callTool('nope', {}); console.log('FAIL unknown tool accepted'); }
catch (e) { console.log('OK unknown tool rejected:', e.message); }

// Reject unknown client on put
try { await callTool('client_put', {client_id:'z',key:'k',value:'v'}); console.log('FAIL unknown client put accepted'); }
catch (e) { console.log('OK unknown client put rejected:', e.message); }

// Reject unknown client on get
try { await callTool('client_get', {client_id:'z',key:'k'}); console.log('FAIL unknown client get accepted'); }
catch (e) { console.log('OK unknown client get rejected:', e.message); }

// Reject non-string/empty
try { await callTool('open_client', {client_id:''}); console.log('FAIL empty client_id accepted'); }
catch (e) { console.log('OK empty client_id rejected:', e.message); }
try { await callTool('open_client', {client_id: 5}); console.log('FAIL number client_id accepted'); }
catch (e) { console.log('OK number client_id rejected:', e.message); }

// Reject extra properties
try { await callTool('open_client', {client_id:'a', extra:'x'}); console.log('NOTE: extra props not enforced at runtime (schema-level)'); }
catch (e) { console.log('OK extra props rejected:', e.message); }

// Isolation check
await callTool('open_client',{client_id:'a'});
await callTool('open_client',{client_id:'b'});
await callTool('client_put',{client_id:'a',key:'k',value:'v'});
const got = await callTool('client_get',{client_id:'a',key:'k'});
console.log('OK a reads own:', got.content[0].text);
try { await callTool('client_get',{client_id:'b',key:'k'}); console.log('FAIL b read a value'); }
catch (e) { console.log('OK b cannot read a value:', e.message); }

// Overwrite returns latest value
await callTool('client_put',{client_id:'a',key:'k',value:'v2'});
const got2 = await callTool('client_get',{client_id:'a',key:'k'});
console.log('OK overwrite:', got2.content[0].text);
"
